// Zone level ranges (arpg_zone_level, generated by sql/tools/gen_zone_levels.py): the world scaling cap (SPEC 4.2,
// task 4.9) and the loot ceiling (SPEC 4.1, task 4.8) both read them.
#ifndef ARPG_LOOT_ZONELEVELS_H
#define ARPG_LOOT_ZONELEVELS_H

#include "Core/LootSubstitution.h"

#include "Define.h"

#include <string>

class Player;

namespace Arpg::Loot
{
    // Startup / .arpg reload. Returns a one-line summary.
    std::string LoadZoneLevels();

    // The zone's range; {0,0} (no ceiling) for unknown zones and for zones in Arpg.Scale.UncappedZones.
    // Tries the zone id, then the area id: Cataclysm re-numbered starting zones (Northshire = zone 6170, but its quests -
    // our source - are filed under the old area 9 "Northshire Valley").
    Core::ZoneLevels ZoneLevelsFor(uint32 zoneId, uint32 areaId = 0);

    // Level loot is made for at the player's current position (zone ceiling; instances: player level).
    int LootLevelFor(Player* player);

}

#endif
